  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} comentaram as cores do pôr do sol.'),
  ('ARRIVAL', 'NEUTRAL', '{user} disse a {user1} que prefere grupos pequenos.'),
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} olharam o salão encher aos poucos.'),
