  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} ouviram o crepitar do fogo sem falar nada.'),
  ('ARRIVAL', 'NEUTRAL', '{user} perguntou a {user1} se sabe nadar. O lago parece gelado.'),
