  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} fizeram fila para o banheiro do térreo.'),
  ('ARRIVAL', 'NEUTRAL', '{user} perguntou a {user1} se tem planos para depois do programa.'),
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} olharam a lua saindo detrás da colina.'),
  ('ARRIVAL', 'NEUTRAL', '{user} contou a {user1} que é influenciador(a) pequeno(a).'),
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} ficaram esperando o jantar no hall.'),
  ('ARRIVAL', 'NEUTRAL', '{user} perguntou a {user1} o que mais sente falta de casa.'),
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} observaram a governanta arrumando a mesa.'),
