INSERT INTO phrases (phase, tone, text) VALUES
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} comentaram que o jantar demorou a sair.'),
  ('ARRIVAL', 'NEUTRAL', '{user} contou a {user1} que é arquiteto(a) e está fascinado(a) pelas paredes.'),
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} olharam juntos o lago escuro atrás do castelo.'),
  ('ARRIVAL', 'NEUTRAL', '{user} perguntou a {user1} se trouxe algum livro.'),
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} ficaram de pé perto do piano sem tocar.'),
  ('ARRIVAL', 'NEUTRAL', '{user} contou a {user1} que é a caçula de cinco irmãos.'),
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} observaram o gaiteiro guardar o instrumento.'),
  ('ARRIVAL', 'NEUTRAL', '{user} perguntou a {user1} se prefere quarto cheio ou vazio.'),
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} tomaram o último gole de vinho da noite.'),
  ('ARRIVAL', 'NEUTRAL', '{user} contou a {user1} que trabalha em hospital há quinze anos.'),
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} olharam o fogo quase apagando.'),
  ('ARRIVAL', 'NEUTRAL', '{user} perguntou a {user1} se ouviu o barulho no telhado.'),
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} conversaram sobre o tempo, literalmente.'),
  ('ARRIVAL', 'NEUTRAL', '{user} contou a {user1} que dirige caminhão pelo país.'),
  ('ARRIVAL', 'NEUTRAL', '{user} e {user1} deram boa noite e subiram em silêncio.'),
  ('ARRIVAL', 'ALLIANCE', '{user} puxou {user1} para o jardim: "Eu e você, desde já."'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Aqui dentro vai ter muita gente. Eu escolho você."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} apertaram as mãos: parceria desde o primeiro dia.'),
  ('ARRIVAL', 'ALLIANCE', '{user} sussurrou para {user1}: "Fica perto de mim. A gente se protege."'),
  ('ARRIVAL', 'ALLIANCE', '{user} combinou com {user1} um código: tocar no brinco quer dizer "precisamos conversar".'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Não conta pra ninguém, mas você é minha primeira escolha."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} prometeram nunca se deixar sozinhos num canto.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Acho que a gente pensa igual. Vamos juntos?"'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} brindaram baixinho: "A nós, até o fim."'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Eu senti que posso confiar em você. Não me decepciona."'),
  ('ARRIVAL', 'ALLIANCE', '{user} ofereceu o dedo mindinho a {user1}. Pacto feito.'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram de sempre sentar lado a lado.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Se alguém falar mal de você, eu te conto."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} decidiram dividir tudo que ouvirem pelos corredores.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Dupla desde a mala. Fechado?"'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} escolheram quartos vizinhos de propósito.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Você cuida das minhas costas, eu das suas."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram um sinal: coçar o nariz é "vem cá".'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Todo mundo precisa de alguém aqui. Eu quero você."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} fizeram um juramento de brincadeira. Meio sério.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "A gente não se conhece, mas confio no meu instinto."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} ficaram de mãos dadas na foto do grupo. Recado dado.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Promete que vai me contar tudo?"'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram de se encontrar toda noite na biblioteca.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Vamos chegar ao final juntos. Nem que seja arrastados."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} trocaram um olhar e já estava tudo combinado.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Ninguém mexe com você enquanto eu estiver aqui."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} decidiram que vão ser um time. Só os dois.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Você me passa segurança. Vamos fechar?"'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram de observar todo mundo e trocar anotações.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Eu sou leal. Até demais. Quer isso do seu lado?"'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} bateram as taças e disseram juntos: "Parceria."'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Guarda meu segredo e eu guardo o seu."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} prometeram não brigar por nada bobo.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Se um de nós cair, o outro segue por dois."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} fizeram uma lista mental de quem parece confiável.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Você tem cara de quem não abandona ninguém."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram que o café da manhã é sempre juntos.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Quero construir algo com você aqui dentro."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} decidiram ser os olhos um do outro.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Não vou prometer nada fácil. Mas prometo lealdade."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} apertaram as mãos debaixo da mesa do jantar.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Se precisar de alguém às três da manhã, sou eu."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram de nunca mentir um pro outro.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Juntos a gente enxerga o castelo inteiro."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} formaram a primeira dupla da casa. Todo mundo reparou.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Me chama de parceiro(a) daqui pra frente."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} se abraçaram no hall: "É nós."'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Eu não quero aliado de conveniência. Quero você."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram de avisar se alguém se aproximar demais.'),
  ('ARRIVAL', 'ALLIANCE', '{user} chamou {user1} e {user2} para a varanda: "Nós três. Que tal?"'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Eu, você e {user2}. Sinto que funciona."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} escolheram {user2} para completar o trio.'),
  ('ARRIVAL', 'ALLIANCE', '{user} sugeriu a {user1}: "Vamos trazer {user2}? Parece gente boa."'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Eu confio em você e em {user2}. Mais ninguém, por enquanto."'),
  ('ARRIVAL', 'ALLIANCE', '{user} reuniu {user1} e {user2} perto da lareira: "Esse é o nosso canto."'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Vamos devagar. Mas vamos juntos."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} ficaram de sentinela no corredor fazendo planos.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Não sou de muitos amigos. Você entrou na lista."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram de defender um ao outro em qualquer discussão.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Você não vai passar por nada sozinho(a) aqui."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} deram um nome secreto para a dupla.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "A gente é o tipo de dupla que ganha. Senti isso."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} dividiram o mesmo cobertor e o mesmo plano.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Se eu ouvir seu nome em conversa, você fica sabendo."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} juraram lealdade na frente da lareira.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Eu escolhi você antes de você abrir a mala."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram de não confiar em mais ninguém tão rápido.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Sabe aquela intuição? Ela diz: fica com essa pessoa."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} ficaram cochichando até o gaiteiro mandar dormir.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Proponho uma coisa: honestidade total entre nós."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} selaram o acordo com um brinde de uísque.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Eu vou te defender até quando você estiver errado(a)."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} decidiram entrar em todas as conversas juntos.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Não é amizade de reality. É de verdade."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} olharam o salão e disseram ao mesmo tempo: "Nós dois."'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Tenho um pressentimento: a gente vai longe junto."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} escolheram um canto do jardim como ponto de encontro.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Pode contar comigo. Pra tudo."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} fizeram uma promessa olhando nos olhos.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Vamos começar certo: juntos."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} deram um aperto de mão exageradamente formal.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Eu sou péssimo(a) sozinho(a). Me adota?"'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} se chamaram de "sócios" pelo resto da noite.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "A gente precisa de alguém pra confiar. Somos nós."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram de trocar impressões sobre cada pessoa.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Eu te protejo, mas você me faz rir. Troca justa."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} foram os últimos a sair do salão, cheios de planos.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Vamos fazer esse castelo ser nosso."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} se entenderam no primeiro olhar. Dupla formada.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Quer ser meu porto seguro aqui?"'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} decidiram dividir segredos só entre os dois.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Juntos. Até quando der."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} prometeram se avisar sobre qualquer fofoca.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Não conheço ninguém. Mas quero conhecer você de perto."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} ficaram de braços dados o jantar inteiro.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Com você eu não tenho medo desse lugar."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} escolheram {user2} como terceiro(a) membro.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1} e {user2}: "Trio de ferro. Ninguém separa."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} olharam para {user2}: "Vem com a gente?"'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "A gente, {user2} e mais ninguém."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram de chamar {user2} amanhã cedo.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Confio em você. Me ajuda a confiar em mais alguém?"'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} fizeram um pacto de proteção mútua na escadaria.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Eu tô com você. Anota isso."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} decidiram que ninguém vai separar a dupla.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Quando ficar difícil, a gente se procura."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} deram as mãos na hora do brinde coletivo.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Você é meu primeiro nome de confiança."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram um olhar para dizer "tá tudo bem".'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Vamos jogar limpo um com o outro. Só isso."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} dividiram a mesma mesa, o mesmo vinho e o mesmo pacto.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Eu vou precisar de você. E você de mim."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} fecharam a primeira parceria da noite.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Se você topar, somos um só daqui em diante."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} ficaram criando apelidos pros outros e planos pra si.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "A gente não precisa de mais ninguém. Por enquanto."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} combinaram de ser sinceros até quando doer.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Não vou te deixar na mão. Palavra."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} fizeram um brinde discreto só entre os dois.'),
  ('ARRIVAL', 'ALLIANCE', '{user} disse a {user1}: "Vai ter muita gente falsa aqui. Nós não."'),
  ('ARRIVAL', 'ALLIANCE', '{user} e {user1} juraram que vão se defender custe o que custar.'),
