INSERT INTO phrases (phase, tone, text) VALUES
  ('BREAKFAST', 'EMOTION', '{user} disse: "Queria poder avisar minha família que eu tô bem."'),
  ('ENDGAME', 'ALLIANCE', '{user} disse a {user1}: "Chegamos juntos. Saímos juntos."'),
  ('ENDGAME', 'ALLIANCE', '{user} segurou a mão de {user1}: "Eu confio em você até o último voto."'),
  ('ENDGAME', 'ALLIANCE', '{user} disse: "Se eu tiver que escolher, escolho {user1}."'),
  ('ENDGAME', 'ALLIANCE', '{user} disse a {user1}: "Desde o primeiro dia, lembra?"'),
