  ('ENDGAME', 'ALLIANCE', '{user} disse: "Eu nunca votei contra {user1}. Não vou começar agora."'),
  ('ENDGAME', 'ALLIANCE', '{user} disse a {user1}: "Juntos na chegada, juntos no prêmio."'),
  ('ENDGAME', 'ALLIANCE', '{user} disse: "A aliança mais antiga do castelo tá aqui."'),
  ('ENDGAME', 'ALLIANCE', '{user} disse a {user1}: "Se for o fim, que seja do seu lado."'),
  ('ENDGAME', 'ALLIANCE', '{user} disse: "Meu voto final acompanha {user1}."'),
  ('ENDGAME', 'ALLIANCE', '{user} disse a {user1}: "Você me carregou até aqui."'),
