  ('ENDGAME', 'ALLIANCE', '{user} disse: "Se {user1} disser ''encerra'', eu encerro."'),
  ('ENDGAME', 'ALLIANCE', '{user} disse a {user1}: "Confio em você mais que no meu próprio instinto."'),
