  ('MISSION', 'HUMOR', '{user} gritou tão alto que o eco respondeu de volta.'),
  ('MISSION', 'HUMOR', '{user} disse: "Eu fui feito(a) pra reality de culinária, não pra isso."'),
  ('MISSION', 'HUMOR', '{user} tentou subir no barco com estilo e caiu com mais estilo ainda.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Sua cara de concentração parece dor de barriga."'),
  ('MISSION', 'HUMOR', '{user} achou a pista e perdeu em três segundos.'),
  ('MISSION', 'HUMOR', '{user} disse que o baú pesava "o mesmo que a culpa dos traidores".'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Me carrega que eu te dou meu sorvete."'),
  ('MISSION', 'HUMOR', '{user} se escondeu atrás de {user1} quando o bode apareceu.'),
  ('MISSION', 'HUMOR', '{user} disse: "Esse bode me olhou com cara de traidor."'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Se eu cair, não me ajuda. Filma."'),
  ('MISSION', 'HUMOR', '{user} tentou nadar cachorrinho e o cachorro da produção se ofendeu.'),
  ('MISSION', 'HUMOR', '{user} disse que a lama entrou em lugares que nem ele(a) conhecia.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "A gente é tipo filme de ação. Da sessão da tarde."'),
  ('MISSION', 'HUMOR', '{user} ficou preso(a) no túnel e disse: "Moro aqui agora."'),
  ('MISSION', 'HUMOR', '{user} disse: "Meu personal ia chorar vendo isso."'),
  ('MISSION', 'HUMOR', '{user} caiu de bunda na lama e fez anjinho.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "A vida é curta. Minha perna também."'),
  ('MISSION', 'HUMOR', '{user} perguntou se o prêmio aceita desconto por esforço.'),
  ('MISSION', 'HUMOR', '{user} disse: "Eu sou péssimo(a) nisso. Mas com muita convicção."'),
  ('MISSION', 'HUMOR', '{user} esqueceu o próprio nome na hora de gritar o grito de guerra.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Não conta pra ninguém que eu tive medo de pato."'),
  ('MISSION', 'HUMOR', '{user} tentou apertar a mão do apresentador e escorregou.'),
  ('MISSION', 'HUMOR', '{user} disse que o colete salva-vidas deixou ele(a) com cara de boia.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Missão hoje, fisioterapia amanhã."'),
  ('MISSION', 'HUMOR', '{user} jurou que a pista estava escrita em élfico.'),
  ('MISSION', 'HUMOR', '{user} disse: "Se eu ganhar o escudo, vou dormir abraçado(a) nele."'),
  ('MISSION', 'HUMOR', '{user} ficou com a cara de quem viu a conta do cartão quando olhou o lago.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Tô tão sujo(a) que virei paisagem."'),
  ('MISSION', 'HUMOR', '{user} tentou empurrar o barco e empurrou {user1} na água.'),
  ('MISSION', 'HUMOR', '{user} disse: "Foi sem querer. Foi quase sem querer."'),
  ('MISSION', 'HUMOR', '{user} perguntou se pode usar o cavalo da fazenda.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Você é rápido(a). Eu sou decorativo(a)."'),
  ('MISSION', 'HUMOR', '{user} bateu a cabeça na viga e disse: "Tô bem. Quem sou eu?"'),
  ('MISSION', 'HUMOR', '{user} disse que a missão é "um spa às avessas".'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Essa missão foi feita por alguém que odeia a gente."'),
  ('MISSION', 'HUMOR', '{user} fez careta pra câmera no meio da prova.'),
  ('MISSION', 'HUMOR', '{user} disse: "Traidor ou não, todo mundo vai sair com gripe."'),
  ('MISSION', 'HUMOR', '{user} caiu do barco antes mesmo de subir.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Olha, eu tentei. Não muito, mas tentei."'),
  ('MISSION', 'HUMOR', '{user} gritou de medo de uma folha.'),
  ('MISSION', 'HUMOR', '{user} disse: "Se a lama fosse ouro, a gente era rico."'),
  ('MISSION', 'HUMOR', '{user} tentou fazer um nó e fez uma trança.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Seu nó parece um laço de presente."'),
  ('MISSION', 'HUMOR', '{user} ficou encantado(a) com uma pedra e esqueceu a missão.'),
  ('MISSION', 'HUMOR', '{user} disse: "Eu tava observando a natureza. Estrategicamente."'),
  ('MISSION', 'HUMOR', '{user} perguntou se tinha como dar ré no barco.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Rema pra frente, amor. Pra frente."'),
  ('MISSION', 'HUMOR', '{user} saiu do lago e tentou secar com uma folha.'),
  ('MISSION', 'HUMOR', '{user} disse: "Eu tô com lama até nos pensamentos."'),
  ('MISSION', 'HUMOR', '{user} gritou "Vitória!" e a equipe tinha perdido.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Detalhes. O importante é a energia."'),
  ('MISSION', 'HUMOR', '{user} tentou pegar o escudo e pegou a perna de {user1}.'),
  ('MISSION', 'HUMOR', '{user} disse: "Desculpa, {user1}. Achei que era o escudo."'),
  ('MISSION', 'HUMOR', '{user} riu tanto do próprio tombo que não conseguiu levantar.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Me ajuda a levantar. Ou me deixa, tô bem aqui."'),
  ('MISSION', 'HUMOR', '{user} disse que a missão foi "inspirada em pesadelos".'),
  ('MISSION', 'HUMOR', '{user} ficou dançando pra se aquecer e acabou chamando atenção de um cervo.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Esse cervo tá me julgando."'),
  ('MISSION', 'HUMOR', '{user} disse que a próxima missão devia ser comer bolo em silêncio.'),
  ('MISSION', 'HUMOR', '{user} ficou com o cabelo em pé de lama seca. "Tendência escocesa."'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Você viu minha bota? Tava no meu pé."'),
  ('MISSION', 'HUMOR', '{user} gritou pro lago: "Devolve meu sapato!"'),
  ('MISSION', 'HUMOR', '{user} disse: "Mais um dia de ouro pro pote e de gelo pra mim."'),
  ('MISSION', 'HUMOR', '{user} jurou que o enigma tinha duas respostas: a certa e a dele(a).'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Eu sou bom(boa) em enigma. Os fáceis."'),
  ('MISSION', 'HUMOR', '{user} tentou fazer abdominal no barco pra se aquecer.'),
  ('MISSION', 'HUMOR', '{user} disse: "Essa é a missão mais longa da minha vida. E mais molhada."'),
  ('MISSION', 'HUMOR', '{user} deu um grito tão agudo que {user1} tapou os ouvidos.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Não é grito, é técnica de respiração."'),
  ('MISSION', 'HUMOR', '{user} fingiu que tinha câimbra pra não entrar na água.'),
  ('MISSION', 'HUMOR', '{user} disse: "Câimbra emocional. Existe."'),
  ('MISSION', 'HUMOR', '{user} usou a bandeira pra se enxugar.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "A bandeira é do grupo. Meu frio também."'),
  ('MISSION', 'HUMOR', '{user} perdeu a corrida pra uma galinha. Literalmente.'),
  ('MISSION', 'HUMOR', '{user} disse: "A galinha teve vantagem. Tinha asa."'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Missão boa é missão com banho quente depois."'),
  ('MISSION', 'HUMOR', '{user} tentou convencer o apresentador de que acertou.'),
  ('MISSION', 'HUMOR', '{user} disse: "Tecnicamente eu acertei. Em outra dimensão."'),
  ('MISSION', 'HUMOR', '{user} ficou fazendo sombra com as mãos no túnel.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Olha, um coelho! Não, é minha mão."'),
  ('MISSION', 'HUMOR', '{user} jurou que ia treinar pra próxima. Não treinou.'),
  ('MISSION', 'HUMOR', '{user} disse: "Minha participação é mais moral do que física."'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Tô tão cansado(a) que dormiria no feno."'),
  ('MISSION', 'HUMOR', '{user} dormiu no feno cinco minutos. Acordaram.'),
  ('MISSION', 'HUMOR', '{user} disse: "Pelo menos agora eu entendo os espantalhos."'),
  ('MISSION', 'HUMOR', '{user} tentou assoviar pra chamar o grupo e cuspiu.'),
  ('MISSION', 'HUMOR', '{user} disse a {user1}: "Meu assovio é mais tímido que eu."'),
  ('MISSION', 'HUMOR', '{user} fez uma reverência depois de errar tudo.'),
  ('MISSION', 'HUMOR', '{user} disse: "Obrigado(a), obrigado(a). Eu erro com classe."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} pediu a palavra e disse que ainda estava ouvindo todos.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} escreveu o nome sem pressa e virou o quadro.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu vou votar com base nos fatos. Só nos fatos."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou em silêncio a discussão inteira.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} olhou para cada rosto antes de escrever.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Não tenho certeza de nada. Mas preciso votar."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} lembrou a todos de manter a calma.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Vamos ouvir todo mundo antes de decidir."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} respirou fundo e pegou o giz.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Meu voto não é pessoal. É estratégia."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} pediu que cada um explicasse o próprio voto.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu mudei de ideia duas vezes hoje."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Não vou me justificar. O voto fala."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou mexendo na vela à frente enquanto pensava.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu sigo meu instinto. Sempre segui."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} observou quem falava mais e quem calava.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Vamos lembrar do que aconteceu ontem."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} lembrou os votos da última mesa.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu vou votar em quem eu tenho mais dúvida."')
ON CONFLICT DO NOTHING;

INSERT INTO phrases (phase, tone, text) VALUES
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou de braços cruzados, esperando a vez.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Não estou convencido(a) por ninguém ainda."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Peço desculpa antecipadamente a quem eu votar."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} escreveu, apagou e escreveu de novo.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu não tenho aliados nessa mesa. Só dúvidas."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} anotou algo num papel antes de votar.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu vou votar com a cabeça, não com o coração."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} pediu que ninguém interrompesse.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Estamos ficando sem tempo. E sem Fiéis."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} olhou para as velas e disse: "Mais uma noite difícil."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu vou ser breve. Meu voto está decidido."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Qualquer escolha hoje é arriscada."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} esperou todos falarem para falar por último.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Não vou acusar ninguém. Vou só votar."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} lembrou que o erro de ontem custou caro.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Vamos pensar nos padrões, não nas emoções."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Essa mesa me assusta mais a cada noite."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} escreveu o nome em letras pequenas.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Meu voto é meu e só meu."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou olhando o quadro em branco por um tempo.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu ouvi coisas hoje que me fizeram pensar."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Acho que estamos todos cansados."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} pediu para o grupo não votar por vingança.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Nenhum voto aqui é fácil."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Vou votar de acordo com o que observei."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou tamborilando os dedos na mesa.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu tenho um nome. Não é certeza, é suspeita."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} olhou para o anfitrião e esperou o sinal.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Vamos acabar logo com isso."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu mudo meu voto se alguém me der um motivo."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Ninguém me convenceu. Nem me desconvenceu."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou atento(a) às reações de quem ia sendo citado.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu não quero errar de novo."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} lembrou quem nunca foi citado em nenhuma mesa.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Cada voto aqui é um tiro no escuro."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} escreveu o nome e colocou o quadro virado.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu não vou me explicar mais do que isso."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Hoje é dia de cabeça fria."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} pediu que todos respeitassem o voto dos outros.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu tô dividido(a) entre dois nomes."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou calado(a) quando perguntaram o voto dele(a).'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Meu voto vai surpreender. Ou não."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Os números importam. Contem com cuidado."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou olhando as chamas das velas.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Não é o que eu quero. É o que precisa ser feito."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu vou votar com a maioria hoje. Por segurança."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Vou votar diferente da maioria. Por consciência."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} pediu um minuto antes de escrever.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Estou cansado(a) de errar."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu confio nos meus olhos. E eles viram coisas."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} escreveu o nome e suspirou.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Não esperem de mim um discurso."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Vamos respeitar quem sair hoje."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} lembrou que o grupo tinha prometido não votar por rancor.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu anotei tudo o que foi dito aqui."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "O silêncio de alguns também é resposta."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou encarando o quadro antes de virar.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Pode ser que eu esteja errado(a). Voto mesmo assim."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Hoje eu voto em quem me deixa mais inquieto(a)."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Não tenho mais nada a dizer. Só o nome."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} olhou para a porta do salão como quem quer sair.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Mais uma mesa, mais um nome."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu vou votar e depois vou dormir. Se conseguir."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "A lógica me leva a um nome só."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} esperou o giz passar pelas mãos dos outros.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Vamos fazer isso direito dessa vez."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu ouço mais do que falo. E ouvi bastante."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou em silêncio após ouvir a última defesa.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "A defesa foi boa. Mas não o suficiente."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "A defesa me convenceu. Mudei de voto."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Não é fácil ser justo(a) aqui."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu voto pensando em quem ainda está aqui, não em quem saiu."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Hoje eu não tenho palpite. Tenho um pressentimento."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} escreveu devagar, letra por letra.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Pra mim, a noite de hoje decide muito."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Vou deixar meu voto falar por mim."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Espero que a gente acerte. Pelo menos uma vez."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} olhou o placar mental dos votos anteriores.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Temos que parar de votar nos quietos."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Temos que parar de votar nos barulhentos."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Não há mais tempo pra dúvida."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou esperando o anfitrião anunciar a votação.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Se eu errar hoje, peço desculpa amanhã."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu não vou virar o voto por pressão."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Um nome. Uma decisão. Pronto."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} ficou olhando as mãos, pensando.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu sei o que vou fazer. Só não sei se tá certo."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Estamos perto do fim. Cada voto pesa mais."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} escreveu e ficou em silêncio até a revelação.'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Eu acho que vai dar empate."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "Pensem bem. Ninguém volta depois."'),
  ('ROUND_TABLE', 'NEUTRAL', '{user} disse: "A gente precisa de um voto unido hoje."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} e {user1} trocaram um olhar e escreveram o mesmo nome.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} bateu levemente o pé no de {user1}: sinal combinado.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "Eu e {user1} vamos votar juntos, sem segredo."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} olhou para {user1} antes de virar o quadro.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "Confio em {user1} de olhos fechados."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} e {user1} assentiram ao mesmo tempo.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "Meu voto e o de {user1} não vão se separar."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} segurou a mão de {user1} por baixo da mesa.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "{user1} é meu(minha) aliado(a). Quem mexe com um, mexe com dois."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} e {user1} fizeram o sinal combinado com as velas.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "Eu sigo {user1} nessa. Ele(a) viu antes."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} cochichou com {user1} antes da votação.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "Eu, {user1} e {user2} estamos alinhados."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} e {user1} escreveram ao mesmo tempo, sem olhar.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "Não vou deixar {user1} sozinho(a) nesse voto."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} piscou para {user1} discretamente.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "Nosso bloco decide hoje."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} e {user1} cruzaram os dedos embaixo da mesa.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "{user1} e eu pensamos igual. Mais uma vez."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} apontou com o queixo para {user1}: combinado.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "Aliança não se discute na mesa. Se vota."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} e {user1} tocaram as taças antes de votar.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "Eu votei com {user1} desde o dia um."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} olhou para {user1} e fez que sim.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "Quem vier contra {user1} vai ter que votar contra mim também."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} e {user1} mantiveram o plano do jardim.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "A gente não muda o voto de última hora."'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} passou o giz para {user1} com um sorriso cúmplice.'),
  ('ROUND_TABLE', 'ALLIANCE', '{user} disse: "{user1}, tô com você. Até o fim."'),
